input = sys.stdin.read

MOD = 998244353

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def solve():
    data = input().strip().split()
    a, b, c = int(data[0]), int(data[1]), int(data[2])

    exponent = a * b + b * c + c * a

    ways_between_clusters = pow(2, exponent, MOD)

    def count_ways_for_cluster(size):
        if size < 3:
            return 1 << (size * (size - 1) // 2)
        return 1 << (size * (size - 1) // 2 - size)

    red_cluster_ways = count_ways_for_cluster(a)
    blue_cluster_ways = count_ways_for_cluster(b)
    purple_cluster_ways = count_ways_for_cluster(c)

    total_ways = (
        ways_between_clusters *
        red_cluster_ways % MOD *
        blue_cluster_ways % MOD *
        purple_cluster_ways % MOD
    ) % MOD

    print(total_ways)

